namespace HagiCode.Libs.Core.AgentWork;

/// <summary>
/// One unit of work the host may be waiting on during a run (a subagent or a monitor).
/// </summary>
/// <param name="Id">
/// Identifier generated by the producing adapter, prefixed with the provider key (for example <c>claude:abc</c>) and
/// stable for the item across the snapshots of one run.
/// </param>
/// <param name="Kind">An open string; <see cref="AgentWorkKinds" /> lists the known values.</param>
/// <param name="ParentId">The <see cref="Id" /> of the item that spawned this one, when there is one.</param>
/// <param name="Status">One of <see cref="AgentWorkStatuses" />.</param>
/// <param name="Title">The task description for a subagent, the tool description for a monitor. May be empty.</param>
/// <param name="Detail">The monitor command, truncated for display.</param>
/// <param name="StartedAt">When the work started (UTC).</param>
/// <param name="EndedAt">When the work reached a terminal status (UTC).</param>
/// <param name="DeadlineAt">For a monitor, its start plus its declared timeout (UTC).</param>
/// <param name="Summary">A subagent's final summary, or the reason a monitor stopped, passed through without rewriting.</param>
/// <param name="Usage">Usage the provider reported, when it did.</param>
/// <param name="ToolUseId">The id of the tool call that launched the work, when known.</param>
/// <param name="BlocksCompletion">Whether the host keeps the run open because of this item.</param>
public sealed record AgentWorkItem(
    string Id,
    string Kind,
    string? ParentId,
    string Status,
    string Title,
    string? Detail,
    DateTimeOffset StartedAt,
    DateTimeOffset? EndedAt,
    DateTimeOffset? DeadlineAt,
    string? Summary,
    AgentWorkUsage? Usage,
    string? ToolUseId,
    bool BlocksCompletion);
